{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated_intermediate as select Null as customer_id ,upper(SHOP_NAME) as SHOP_NAME ,upper(coalesce(case when lower(marketplace) like \'%amazon%\' then \'AMAZON\' end, case when lower(email) in (\'ishita@sleepycat.in\',\'marketing@sleepcat.in\') then \'MARKETING\' end, (m_w.channel),(m_s.channel),(m_p.channel) ,case when (lower(reference_code) like \'pos%\' or lower(replace(reference_code,\'_\',\'&\')) like \'%&ght&store\') then \'RETAIL\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'P%\',\'%$P%\') then \'PEPPERFRY\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$STOWS%\') then \'Wooden Street\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$WS%\') then \'Wooden Street\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$B2B%\') then \'B2B\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$AS%\') then \'B2B\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$TEST%\') then \'TEST\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$C%\') then \'COVER\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$MKT%\') then \'Marketing\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$WKT%\') then \'Marketing\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$COMP%\') then \'Marketing\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any (\'%$SWST%\') then \'Springwell\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any(\'E%\',\'%$E%\') then \'EXCHANGE\' when UPPER(replace(b.reference_code,\'_\',\'$\')) like any(\'R%\',\'%$R%\') then \'REPLACEMENT\' when UPPER(reference_code) like \'B2B%\' then \'B2B\' when UPPER(reference_code) like \'TEST%\' then \'TEST\' when UPPER(reference_code) like any (\'C%\',\'COMP%\', \'MKT%\') then \'MARKETING\' when UPPER(reference_code) like \'WKT%\' then \'WELCOME KIT\' when REGEXP_LIKE(UPPER(reference_code), \'(.*_E|.*_E1|.*_E2|.*_E3|.*_E4|.*_E5)\') then \'EXCHANGE\' when REGEXP_SUBSTR(UPPER(reference_code), \'^(.*_R.*|.*_RPL.*)$\') IS NOT NULL then \'REPLACEMENT\' when REGEXP_LIKE(UPPER(reference_code), \'(.*_C|.*_C1|.*_C2|.*_C3|.*_CP|.*_COVER)\') then \'MARKETING\' when upper(reference_code) like any (\'MKT%\',\'INV%\',\'%SAM%\') then \'MARKETING\' when REGEXP_LIKE(UPPER(reference_code), \'(.*_CP|.*_COMP)\') and ifnull(selling_price,0) < 10 then \'MARKETING\' when UPPER(reference_code) like any (\'WS%\',\'STOWS%\') then \'WOODEN STREET\' when UPPER(reference_code) like \'PPF%\' or (lower(marketplace) like \'%offline%\' and lower(reference_code) like any (\'309%\') and length(reference_code) >= 9 and length(reference_code) <= 11) then \'PEPPERFRY\' else upper(marketplace) end)) as marketplace ,upper(coalesce(wfi.utm_mapped_channel,ga.ga_channel,final_utm_channel,b.marketplace)) AS CHANNEL ,upper(coalesce(wfi.utm_mapped_source,ga.ga_source,final_utm_Source,b.marketplace)) AS SOURCE ,b.COMPANY_NAME ,b.ORDER_ID ,reference_code ,contact_num as PHONE ,customer_name as NAME ,location_key ,email as EMAIL ,shipping_last_update_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,b.common_skucode as COMMON_SKU_CODE ,PRODUCT_ID::String product_id ,upper(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,upper(CITY) City ,upper(STATE) AS State ,upper(ORDER_STATUS) as Order_Status ,ORDER_DATE::timestamp AS Order_Date ,case when lower(marketplace) like \'%woocommerce%\' then SUBORDER_QUANTITY * ifnull(qty,1) else SUBORDER_QUANTITY end AS PRE_QUANTITY ,case when lower(marketplace) like \'%woocommerce%\' then (SUBORDER_QUANTITY * ifnull(\"Item Quantity Multiplier\",1) * ifnull(qty,1)) else (SUBORDER_QUANTITY * ifnull(\"Item Quantity Multiplier\",1)) end AS QUANTITY ,ifnull(SELLING_PRICE,0)-ifnull(tax,0)+ifnull(DISCOUNT,0) AS GROSS_SALES_BEFORE_TAX ,(b.mrp_sales)as total_mrp ,coalesce ((total_mrp-SELLING_PRICE),DISCOUNT) AS DISCOUNT ,coalesce ((SELLING_PRICE - div0(SELLING_PRICE,1+div0(try_to_double(replace(mrp_map.gst,\'%\',\'\')),100))),TAX) as TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,upper(ORDER_STATUS) as OMS_Order_Status ,upper(b.Shipping_status) AS SHIPPING_STATUS ,upper(case when lower(shipmap.final_shipping_status) like \'%cancel%\' or lower(b.shipping_status) like \'%cancel%\' or lower(ORDER_STATUS) like \'%cancel%\' then \'cancelled\' else coalesce(shipmap.final_shipping_status,b.shipping_status) end) FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID::string as SALEORDERITEMCODE ,suborder_id::string as SALES_ORDER_ITEM_ID ,AWB ,upper(wfi.payment_gateway) Payment_Gateway ,upper(coalesce(b.payment_mode,wfi.payment_method)) Payment_Mode ,UPPER(COURIER) COURIER ,MANIFEST_DATE as DISPATCH_DATE ,DELIVERED_DATE ,case when lower(coalesce(ShipMap.shipping_status,b.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,case when IS_REFUND=1 or rt.reference_code1 is not null then 1 end RETURN_FLAG ,case when RETURN_FLAG = 1 then suborder_quantity::int end returned_quantity ,case when RETURN_FLAG = 1 and lower(order_status) not in (\'cancelled\') then ifnull(coalesce(rt.TOTAL_RETURN_AMOUNT,SELLING_PRICE),0) end returned_sales ,case when is_refund = 0 and lower(order_status) in (\'cancelled\') then suborder_quantity::int end cancelled_quantity ,new_customer_flag::varchar as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,Days_in_shipment AS DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,SKU as SKU_CODE ,upper(mapped_product_name) as PRODUCT_NAME_FINAL ,upper(mapped_category) as PRODUCT_CATEGORY ,upper(mapped_sub_category) as PRODUCT_SUB_CATEGORY ,upper(WAREHOUSE_NAME) WAREHOUSE ,pin_code Destination_Pincode ,pickup_pin_code SOURCE_PINCODE ,PAYMENT_GATEWAY_TRANSACTION_NUMBER ,Suborder_id::string subordeR_id ,case when AOVE.order_id is not null then \'1\' else \'0\' end ORDER_INCLUSION_FLAG ,ORDER_TYPE as Invoice_Order_Type ,PAYMENT_GATEWAY_NAME ,number_of_products_in_combo as item_Quantity_from_easyecom from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS b left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from SLEEPYCAT_DB.MAPLEMONK.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,b.order_status)) = lower(ShipMap.shipping_status) left join ( select * from ( select transactionid ,upper(channel) ga_channel ,upper(final_source) ga_source ,row_number() over (partition by transactionid order by 1) rw from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_GA_ORDER_BY_SOURCE_CONSOLIDATED ) where rw = 1 ) ga on b.reference_code = ga.transactionid left join ( select order_number,final_utm_channel,final_utm_source from sleepycat_db.maplemonk.dwh_Shopify_All_orders qualify row_number() over(partition by order_number order by 1) = 1 )shopify on replace(shopify.order_number,\'#\',\'\') = replace(b.reference_code,\'#\',\'\') LEFT JOIN ( select * from (select order_id as id1, utm_medium, utm_source, utm_campaign, utm_content, utm_path, utm_mapped_source, utm_mapped_channel, payment_gateway, payment_method, row_number() over (partition by order_id order by 1) rw from SLEEPYCAT_DB.MAPLEMONK.SleepyCat_DB_Woocommerce_FACT_ITEMS ) where rw=1 )wfi on wfi.id1 = b.reference_code left join ( select * from ( select *, row_number() over(partition by sku_code order by end_date) rw from sleepycat_db.maplemonk.sku_mrp_cogs ) where rw=1 )mrp_map on lower(b.sku) = lower(mrp_map.sku_code) left join ( select suborder_id as suborder_id1 , reference_code as reference_code1 , sum(TOTAL_RETURN_AMOUNT) as TOTAL_RETURN_AMOUNT from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_easyecom_returns_intermediate group by 1,2 )rt on b.reference_code = rt.reference_code1 and rt.suborder_id1 = b.suborder_id left join (select order_id from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS GROUP BY ORDER_ID HAVING sum(SELLING_PRICE) > 50 ) AOVE on b.order_id = AOVE.order_id left join ( select * from ( select *,row_number() over(partition by suffix order by 1)rw from sleepycat_db.maplemonk.marketplace_suffix ) where rw=1 and suffix is not null )m_s on lower(replace(b.reference_code,\'_\',\'$\')) like \'%\' || lower(replace(m_s.suffix,\'_\',\'$\')) left join ( select * from ( select *,row_number() over(partition by prefix order by 1)rw from sleepycat_db.maplemonk.marketplace_suffix ) where rw=1 and prefix is not null )m_p on lower(replace(b.reference_code,\'_\',\'$\')) like lower(replace(m_p.prefix,\'_\',\'$\')) || \'%\' left join ( select * from ( select *,row_number() over(partition by withinorder order by 1)rw from sleepycat_db.maplemonk.marketplace_suffix ) where rw=1 and withinorder is not null )m_w on lower(replace(b.reference_code,\'_\',\'$\')) like \'%\' || lower(replace(m_w.withinorder,\'_\',\'$\')) || \'%\' left join ( select skucode as p_sku,qty from sleepycat_db.maplemonk.sleepycat_db_sku_mapping_parent_child qualify row_number() over(partition by skucode order by 1) = 1 )pc on lower(b.sku) = lower(pc.p_sku) where (lower(ifnull(B.customer_name,\'\')) not in (select lower(STN_Customer_Name) from sleepycat_db.maplemonk.stock_transfer_customers ) ) AND not(upper(reference_code) like \'STN%\') union all select Null as customer_id ,upper(SHOP_NAME) as SHOP_NAME ,upper(shop_name) as marketplace ,upper(shop_name) AS CHANNEL ,upper(shop_name) AS SOURCE ,null COMPANY_NAME ,ORDER_ID ,ordeR_name reference_code ,null PHONE ,name as NAME ,null location_key ,null as EMAIL ,invoice_date AS SHIPPING_LAST_UPDATE_DATE ,SKU ,sku as COMMON_SKU_CODE ,product_id PRODUCT_ID ,upper(PRODUCT_NAME) AS PRODUCT_NAME ,null CURRENCY ,upper(CITY) City ,upper(STATE) AS State ,\'DELIVERED\' as Order_Status ,ORDER_DATE::timestamp AS Order_Date ,quantity PRE_QUANTITY ,quantity AS QUANTITY ,ifnull(gross_sales_before_tax,0) AS GROSS_SALES_BEFORE_TAX ,null as total_mrp ,DISCOUNT , TAX ,SHIPPING_PRICE ,total_sales AS SELLING_PRICE ,\'DELIVERED\' as OMS_Order_Status ,\'DELIVERED\' AS SHIPPING_STATUS ,\'DELIVERED\' FINAL_SHIPPING_STATUS ,Line_Item_ID as SALEORDERITEMCODE ,Line_Item_ID as SALES_ORDER_ITEM_ID ,null AWB ,null Payment_Gateway ,payment_type Payment_Mode ,null COURIER ,null DISPATCH_DATE ,null DELIVERED_DATE ,\'1\' AS DELIVERED_STATUS ,is_refund RETURN_FLAG ,case when RETURN_FLAG = 1 then quantity::int end returned_quantity ,case when RETURN_FLAG = 1 and lower(order_status) not in (\'cancelled\') then ifnull(total_sales,0) end returned_sales ,null cancelled_quantity ,null as NEW_CUSTOMER_FLAG ,NULL as ACQUISITION_PRODUCT ,null DAYS_IN_SHIPMENT ,NULL AS ACQUSITION_DATE ,SKU as SKU_CODE ,upper(mapped_product_name) as PRODUCT_NAME_FINAL ,upper(mapped_producT_category) as PRODUCT_CATEGORY ,upper(mapped_product_sub_category) as PRODUCT_SUB_CATEGORY ,upper(WAREHOUSE_ID) WAREHOUSE ,pincode Destination_Pincode ,null SOURCE_PINCODE ,null PAYMENT_GATEWAY_TRANSACTION_NUMBER ,null Suborder_id ,\'1\' ORDER_INCLUSION_FLAG ,event_type as Invoice_Order_Type ,null PAYMENT_GATEWAY_NAME ,quantity as item_Quantity_from_easyecom from sleepycat_db.maplemonk.Flipkart_sales_fact_items where event_type = \'Sale\' and fulfilment_type = \'FBF\' and lower(concat(ordeR_name, sku)) not in (select distinct lower(concat(reference_code, sku)) from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_EasyEcom_FACT_ITEMS where ordeR_status not in (\'RETURNED\')) ; create or replace table SLEEPYCAT_DB.MAPLEMONK.Final_customerID as with new_phone_numbers as ( select phone, contact_num, 19700000000 + row_number() over( order by contact_num asc ) as maple_monk_id from ( select distinct right(regexp_replace(phone, \'[^a-zA-Z0-9]+\'),10) as contact_num, phone from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated_intermediate ) a ), int as ( select contact_num, email, coalesce(maple_monk_id,id2) as maple_monk_id from ( select contact_num, email, maple_monk_id, 19800000000+row_number() over(partition by maple_monk_id is NULL order by email asc ) as id2 from ( select distinct coalesce(p.contact_num,right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10)) as contact_num, e.email, maple_monk_id from ( select phone as contact_num, email from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated_intermediate ) e left join new_phone_numbers p on p.contact_num = right(regexp_replace(e.contact_num, \'[^a-zA-Z0-9]+\'),10) ) a ) b ) select contact_num, email, maple_monk_id from int where coalesce(contact_num,email) is not NULL; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated as select coalesce(m.maple_monk_id_phone, d.maple_monk_id) as customer_id_final, min(order_date) over(partition by customer_id_final) as acquisition_date, min(case when lower(order_status) not in (\'cancelled\') then order_date end) over(partition by customer_id_final) as first_complete_order_date, m.* from ( select c.maple_monk_id as maple_monk_id_phone, o.* from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated_intermediate o left join ( select * from ( select contact_num phone, maple_monk_id, row_number() over (partition by contact_num order by maple_monk_id asc) magic from SLEEPYCAT_DB.MAPLEMONK.Final_customerID ) where magic =1 )c on c.phone = right(regexp_replace(o.phone, \'[^a-zA-Z0-9]+\'),10) )m left join ( select distinct maple_monk_id, email from SLEEPYCAT_DB.MAPLEMONK.Final_customerID where contact_num is null )d on d.email = m.email; ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated drop COLUMN new_customer_flag ; ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ADD COLUMN new_customer_flag varchar(50); ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ADD COLUMN new_customer_flag_month varchar(50); ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated drop COLUMN acquisition_product ; ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ADD COLUMN acquisition_product varchar(16777216); ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ADD COLUMN acquisition_channel varchar(16777216); ALTER TABLE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ADD COLUMN acquisition_marketplace varchar(16777216); UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date then \'New\' WHEN Order_Date < first_complete_order_date or first_complete_order_date is null THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date then \'Repeat\' END AS Flag FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' WHEN new_customer_flag IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) in (\'cancelled\') end) THEN \'Yet to make completed order\' ELSE new_customer_flag END; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, Order_Date, CASE WHEN Last_day(order_date, \'month\') = Last_day(first_complete_order_date, \'month\') THEN \'New\' WHEN Last_day(order_date, \'month\') < Last_day(first_complete_order_date, \'month\') or acquisition_date is null THEN \'Yet to make completed order\' WHEN Last_day(order_date, \'month\') > Last_day(first_complete_order_date, \'month\') THEN \'Repeat\' END AS Flag FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated)AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL and (case when lower(order_status) is null then 1=1 else lower(order_status) not in (\'cancelled\') end) THEN \'New\' ELSE new_customer_flag_month END; CREATE OR replace temporary TABLE SLEEPYCAT_DB.MAPLEMONK.temp_source_1 AS SELECT DISTINCT customer_id_final, channel, marketplace FROM ( SELECT DISTINCT customer_id_final, order_date, source as channel, shop_name as marketplace, Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated ) res WHERE order_date=firstorderdate; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS a SET a.acquisition_channel=b.channel FROM SLEEPYCAT_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS a SET a.acquisition_marketplace=b.marketplace FROM SLEEPYCAT_DB.MAPLEMONK.temp_source_1 b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE SLEEPYCAT_DB.MAPLEMONK.temp_product_1 AS SELECT DISTINCT customer_id_final, product_name_final, Row_number() OVER (partition BY customer_id_final ORDER BY SELLING_PRICE DESC) rowid FROM ( SELECT DISTINCT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated )res WHERE order_date=firstorderdate; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS A SET A.acquisition_product=B.product_name_final FROM ( SELECT * FROM SLEEPYCAT_DB.MAPLEMONK.temp_product_1 WHERE rowid=1 )B WHERE A.customer_id_final = B.customer_id_final; UPDATE SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated AS A SET A.marketplace = B.marketplace, A.shop_name = B.shop_name FROM ( SELECT reference_code ,marketplace ,shop_name FROM SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated qualify row_number() over(partition by reference_code order by reference_code) = 1 )B WHERE SPLIT_PART(A.reference_code,\'_\',1) = B.reference_code and (LOWER(A.marketplace) LIKE \'%exchange%\' OR LOWER(A.marketplace) LIKE \'%replacement%\' OR LOWER(A.marketplace) LIKE \'%offline%\') ; Create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_Offline_Store_Fact_Items as select * from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated WHERE (upper(reference_code) RLIKE \'^[0-9]{10}_SWST.*\'); create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated as select sc.*,wc.\"Warehouse City\" as mapped_warehouse_city ,nwc.\"Nearest Warehouse\" as nearest_warehouse ,case when lower(mapped_warehouse_city) = lower(nearest_warehouse) then \'LOCAL\' else \'NON-LOCAL\' end as warehouse_proximity ,cs.state as mapped_state ,cs.city as mapped_city ,cs.\"City Tier\" as CITY_TIER ,cs.DIRECTION as DIRECTION ,prs.priority ,prs.fullfillment ,case when lower(\"Warehouse City\") = \'hyderabad\' then hyderabad when lower(\"Warehouse City\") = \'mumbai\' then mumbai when lower(\"Warehouse City\") = \'chennai\' then chennai when lower(\"Warehouse City\") = \'gurgaon\' then gurgaon when lower(\"Warehouse City\") = \'bangalore\' then bangalore end as WarehousePrioritySKU from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated sc left join (select * from ( select *,row_number() over(partition by lower(warehouse) order by 1 )rw from sleepycat_db.maplemonk.sleepycat_db_warehouse_city_mapping )where rw = 1 )wc on lower(wc.warehouse) = lower(sc.warehouse) left join (select * from ( select *,row_number() over(partition by pincode order by 1 )rw from sleepycat_db.maplemonk.sleepycat_db_pincode_nearest_warehouse_mapping )where rw = 1 )nwc on lower(nwc.pincode) = lower(sc.destination_pincode) left join ( select * from sleepycat_db.maplemonk.sleepycat_db_pincode_city_state_mapping qualify row_number() over(partition by pincode order by 1 ) = 1 )cs on sc.destination_pincode = cs.pincode left join ( Select sku as pioritySKU, priority, mumbai, chennai, gurgaon, bangalore, hyderabad, fullfillment from sleepycat_db.maplemonk.sku_wise_priority_mapping qualify row_number() over(partition by lower(trim(sku)) order by 1) = 1 )prs on lower(prs.pioritySKU) = lower(sc.sku) WHERE not(upper(reference_code) RLIKE \'^[0-9]{10}_SWST.*\'); Create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_easyecom_returns_fact_items as select ifnull(FE.Source,\'NA\') Marketing_CHANNEL ,FE.marketplace as original_marketplace ,FR.* from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_easyecom_returns_intermediate FR left join (select distinct replace(reference_code,\'#\',\'\') REFERENCE_CODE, Source,marketplace from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated) FE on FR.REFERENCE_CODE = FE.REFERENCE_CODE; create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_RETURNS_CONSOLIDATED as select upper(MARKETPLACE) Marketplace ,Marketing_CHANNEL ,Return_Date ,last_update_date::date as last_update_date ,sum(RETURNED_QUANTITY) TOTAL_RETURNED_QUANTITY ,sum(TOTAL_RETURN_AMOUNT) TOTAL_RETURN_AMOUNT ,sum(RETURN_TAX) TOTAL_RETURN_TAX ,sum(RETURN_AMOUNT_WITHOUT_TAX) TOTAL_RETURN_AMOUNT_EXCL_TAX from SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_easyecom_returns_fact_items where credit_note_number <> \'0\' group by 1,2,3,4 order by 2 desc; Create or replace table SLEEPYCAT_DB.MAPLEMONK.SLEEPYCAT_DB_sales_consolidated as select \'Sales\' as type ,marketplace ,lower(company_name) as company_name ,SHOP_NAME ,CHANNEL ,REFERENCE_CODE ,ORDER_ID ,SKU ,PRODUCT_ID::string as PRODUCT_ID ,PRODUCT_NAME ,PRODUCT_NAME_FINAL ,TRIM(PRODUCT_CATEGORY) AS PRODUCT_CATEGORY ,TRIM(PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY ,ORDER_DATE::date as order_date ,null as final_return_date ,CUSTOMER_ID_FINAL ,ACQUISITION_DATE ,order_date as order_timestamp ,FIRST_COMPLETE_ORDER_DATE ,MAPLE_MONK_ID_PHONE ,CUSTOMER_ID ,SOURCE ,PHONE ,NAME ,EMAIL ,SHIPPING_LAST_UPDATE_DATE ,COMMON_SKU_CODE ,CURRENCY ,CITY ,ST