urn\' order_type, event_type, null as priority, null as fullfillment, null as WarehousePrioritySKU, null location_key, null as PAYMENT_GATEWAY_NAME, null as item_Quantity_from_easyecom, null as return_type, null as return_reason from sleepycat_db.maplemonk.Flipkart_sales_fact_items where event_type = \'Return\' ; create or replace table sleepycat_db.maplemonk.sleepycat_db_npd_sku_fact_items as select * from sleepycat_db.maplemonk.sleepycat_db_sales_consolidated where lower(sku) in( select distinct lower(sku) sku from sleepycat_db.maplemonk.sleepycat_db_npd_performance ) ;",
